import math
def change_point(xs):
    n = len(xs)
    pre = [0.0]
    for x in xs:
        pre.append(pre[-1] + x)
    best, arg = -1.0, 1
    for k in range(1, n):
        m1, m2 = pre[k] / k, (pre[n] - pre[k]) / (n - k)
        s = abs(m1 - m2) * math.sqrt(k * (n - k) / n)
        if s > best:
            best, arg = s, k
    return arg
